import unittest
import division as div  #filnamn

class TestDivision(unittest.TestCase):

    def test_division(self):
        self.assertEqual(div.division(10,2), 5)

    def test_division_value(self):
        """Kontrollerar att ValueError ges vid nolldivision"""
        with self.assertRaises(ValueError):
            div.division(17, 0)

if __name__ == '__main__':
  unittest.main()

# Detta är ett utdrag ur filen med funktioner som ska testas
def division(a,b):
	if( b == 0):
		raise ValueError("Ej delbart med 0")
	return a/b
